from typing import Union, Optional, List, Literal, TypedDict, Unpack
from datetime import datetime

from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.client.decorators import api_version_check
from pyvkteamsclient.tracer import tracer


class ModChatKwargs(TypedDict):
    name: str
    about: str
    rules: str
    public: bool
    joinModeration: bool
    lookingEnabled: bool
    stamp: str
    trustRequired: bool
    threadsEnabled: bool


class ModChatMemberKwargs(TypedDict):
    sn: str
    stamp: str


class GetChatInfoKwargs(TypedDict):
    sn: str
    stamp: str


class GroupSubscribeKwargs(TypedDict):
    stamp: str
    chatId: str


class ChatMembersKwargs(TypedDict):
    cursor: str


class ChatsMethods(BaseClient):
    """
    Методы группы 'Группы' из https://im-docs.corp.mail.ru/
    """

    @api_version_check(min_version=1)
    @tracer.start_as_current_span("chats.rapi_createChat")
    def rapi_createChat(
        self,
        name: str = "Test group - autotest.release",
        avatarId: str = "",
        members: Union[tuple[str, ...], list[str]] = (),
        about: str = "Something new about this group",
        rules: str = "Some rules of this group",
        public: bool = True,
        joinModeration: bool = True,
        defaultRole: Literal["member", "admin", "readonly"] = "member",
    ) -> dict:
        """
        При создании можно указать различные параметры группы.
        После создания их можно будет поменять с помощью метода /rapi/modChat.

        Что бы получить avatarId нужно предварительно
        загрузить аватар через метод /files/avatar/set
        с флагом beforehandUpload. Существуют ограничения на длину названия,
        описания и правил группы - их задают администраторы кластера.
        Параметр defaultRole определяет будет ли это группа или канал.
        :param name: Название группы
        :param avatarId: ID аватара группы
        :param members: список ID пользователей,
        которых нужно добавить в группу
        :param about: Описание группы
        :param rules: Правила группы
        :param public: Публичность группы
        :param joinModeration: Флаг премодерации на вступление в группу/канал
        :param defaultRole: Роль новых участников группы при вступлении
        :return: тело ответа сервера
        """
        result = self.post(
            "rapi/createChat",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {
                    "name": name,
                    "avatarId": avatarId,
                    "members": [{"sn": member} for member in members],
                    "about": about,
                    "rules": rules,
                    "public": public,
                    "joinModeration": joinModeration,
                    "defaultRole": defaultRole,
                },
            },
        )

        self.created_chats.add(result["results"]["sn"])
        return result

    @api_version_check(min_version=5)
    @tracer.start_as_current_span("chats.rapi_joinChat")
    def rapi_joinChat(self, stamp: str) -> dict:
        """
        В методе происходит ряд проверок на то,
        может ли пользователь вступить в указанную группу.

        Если в группе стоит флаг joinModeration,
        то вступление произойдёт только после
        подтверждения администратором группы.
        Администратор может изменить роль участника группы
        с помощью метода /rapi/modChatMember.

        Покинуть группу можно с помощью метода /rapi/contacts/delete.
        :param stamp: Уникальный алиас для группы/канала
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/joinChat",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"stamp": stamp},
            },
        )

    @api_version_check(min_version=1)
    @tracer.start_as_current_span("chats.rapi_modChat")
    def rapi_modChat(self, sn: str, **kwargs: Unpack[ModChatKwargs]) -> dict:
        r"""
        Только администратор группы может изменить параметры группы.

        Существуют ограничения на длину названия,
        описания и правил группы - их задают администраторы кластера.
        :param sn: Идентификатор группы
        param name: Новое название группы \n
        param about: Новое описание группы \n
        param rules: Новые правила группы \n
        param public: Публичная ли группа \n
        (будет ли отображаться в поиске и витрине чатов)
        param joinModeration: Требуется ли разрешение администратора
        на вступление в группу \n
        param lookingEnabled: Флаг отображения голов и просмотров в группе \n
        param stamp: Новый уникальный алиас для группы \n
        param trustRequired: Требуется ли доверие
        к клиенту для скачивания файла \n
        :return: тело ответа сервера
        """
        params = {"sn": sn, **kwargs}

        return self.post(
            "rapi/modChat",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": params,
            },
        )

    @api_version_check(min_version=5)
    @tracer.start_as_current_span("chats.rapi_modChatMember")
    def rapi_modChatMember(self, memberSn: str, role: str = "admin", **kwargs: Unpack[ModChatMemberKwargs]) -> dict:
        r"""
        Только администратор группы может изменить роль участника.
        :param memberSn: Уникальный идентификатор участника группы
        param sn: Идентификатор группы \n
        param stamp: Уникальный алиас для группы \n
        :param role: Новая роль участника группы
        :return: тело ответа сервера
        """
        if "sn" not in kwargs and "stamp" not in kwargs:
            raise ValueError("One of params must be specified: sn or stamp")

        else:
            json_data = {
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {**kwargs, "memberSn": memberSn, "role": role},
            }

            return self.post("rapi/modChatMember", headers={"Content-Type": "application/json"}, json=json_data)

    @api_version_check(min_version=1)
    @tracer.start_as_current_span("chats.rapi_getChatInfo")
    def rapi_getChatInfo(self, memberLimit: int = 5, **kwargs: Unpack[GetChatInfoKwargs]) -> dict:
        r"""
        Возвращает информацию о группе.
        Кроме того, возвращает cписок пользователей members,
        размер которого зависит от параметра memberLimit;
        состояние пользователя в чате you: роль, заблокирован пользователь
        или находится в очереди на вступление;
        sn того кто добавил или номинировал пользователя на добавление в чат.

        Групповой чат всегда live - имеет ссылку.
        В controlled чатах только создатель может добавлять,
        удалять участников; менять анкету чата. privatized -
        чат не может стать публичным. Чат может быть public только если
        он не privatized и не blocked. privatized/blocked выставляются
        только модераторами ICQ. В заблокированном чате учатники
        не могут делать ничего, кроме как получить информацию
        о чате и список участников.

        Булевы поля приходят только если они true.

        Запрос по sn разрешен только для участников группы.
        param sn: Идентификатор группы \n
        param stamp: Уникальный алиас для группы \n
        :param memberLimit: Лимит на количество возвращаемых участников чата
        :return: тело ответа сервера
        """
        if "sn" not in kwargs and "stamp" not in kwargs:
            raise ValueError("One of params must be specified: sn or stamp")
        else:
            json_data = {
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {**kwargs, "memberLimit": memberLimit},
            }

            return self.post("rapi/getChatInfo", headers={"Content-Type": "application/json"}, json=json_data)

    @api_version_check(min_version=3)
    @tracer.start_as_current_span("chats.rapi_getChatMembers")
    def rapi_getChatMembers(
        self,
        _id: str,
        pageSize: int = 666,
        filter_role: str = "admins | members " "| blocked | pending | invitations",
        **kwargs: Unpack[ChatMembersKwargs],
    ) -> dict:
        """
        Filter и cursor - взаимоисключающие параметры.
        В каждом ответе сервер возвращает
        курсор для запроса следующей страницы.
        Если в ответе сервера нет поля cursor,
        была запрошена последняя страница.
        Время жизни поисковой сессии - 5 минут с момента последнего запроса.
        Если использовать курсор по истечении этого времени,
        вернется первая страница обновленной выдачи со статусом "20002"
        :param _id: Id чата
        :param pageSize: Лимит на количество возвращаемых участников чата
        :param filter_role: Роль возвращаемых участников чата
        :param cursor: Курсор для запроса следующей страницы
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/getChatMembers",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {
                    "id": _id,
                    "pageSize": pageSize,
                    "filter": {"role": filter_role},
                    **kwargs,
                },
            },
        )

    @api_version_check(min_version=2)
    @tracer.start_as_current_span("chats.rapi_searchChatMembers")
    def rapi_searchChatMembers(
        self,
        _id: str,
        pageSize: int = 666,
        filter_role: str = "admins | members " "| blocked | pending | invitations",
        keyword: Optional[str] = None,
        **kwargs: Unpack[ChatMembersKwargs],
    ):
        """
        Метод для поиска по участникам чата.

        Для пагинации используется cursor.
        Если cursor не пришел, значит достигнута последняя страница.
        При пагинации не перестраивает список.
        Если поле фильтр отсутствует, то выдаем админов и мемберов.

        Значение роли может быть одним из:
        admin, blocked, pending, invitations.

        :param _id: Id чата
        :param pageSize: Лимит на количество возвращаемых участников чата
        :param filter_role: Роль возвращаемых участников чата
        :param cursor: Курсор для запроса следующей страницы
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/searchChatMembers",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {
                    "id": _id,
                    "pageSize": pageSize,
                    "filter": {"keyword": keyword, "role": filter_role},
                    **kwargs,
                },
            },
        )

