    @api_version_check(min_version=1)
    @tracer.start_as_current_span("chats.rapi_group_members_add")
    def rapi_group_members_add(self, sn: str, members: List[str], confirmUnblock: bool = True) -> dict:
        """
        Если у группы или канала включена настройка "Вступление по запросу"
        и отправитель запроса не является администратором в этой группе/канале,
         то пользователи будут добавлены в список ожидающих
         подтверждения от администраторов.
         В этом случае добавляющий может отменить свой запрос
         на добавление других пользователей
          при помощи метода /rapi/group/invitations/cancel

        В дальнейшем удалить участников из группы могут
        администраторы при помощи метода /rapi/group/members/delete.

        :param sn: Идентификатор группы
        :param members: Список идентификаторов пользователей (sn или nick),
        добавляемых в группу
        :param confirmUnblock: Добавить пользователя в группу,
        даже если он заблокирован.
        Параметр имеет действие,
        только если запрос выполняется администратором группы или канала
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/group/members/add",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {
                    "sn": sn,
                    "confirmUnblock": confirmUnblock,
                    "members": members,
                },
            },
        )

    @api_version_check(min_version=22)
    @tracer.start_as_current_span("chats.rapi_group_members_delete")
    def rapi_group_members_delete(self, sn: str, members: List[str]) -> dict:
        """
        Метод для удаления пользователей из группы или канала без блокировки.
        Для удаления участников с блокировкой
        следует использовать метод /rapi/blockChatMembers.

        Участники группы могут использовать этот метод
        для удаления ошибочно добавленных пользователей
        в течение первых 10 минут после добавления (конфигурируемо).

        Администраторы группы могут удалять участников
        без временных ограничений.

        Участникам и администраторам
        не следует использовать этот метод для того,
        чтобы самостоятельно покинуть группу или канал.
        Для этих целей необходимо использовать метод /wim/buddylist/hideChat.

        :param sn: Идентификатор группы
        :param members: Список sn пользователей, удаляемых из группы
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/group/members/delete",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"sn": sn, "members": members},
            },
        )

    @api_version_check(min_version=1)
    @tracer.start_as_current_span("chats.rapi_checkGroupStamp")
    def rapi_checkGroupStamp(self, stamp: str) -> dict:
        """
        Проверяет можно ли занять штамп, а так же проверяет валидность
        данного штампа,
        в случае если переданный штамп не соответствует формату,
        сервер вернет 40000.

        Штамп должен соответствовать следующим критериям:

        Длина штампа (от 5 до 30) символов.
        Первый символ является латинской буквой в нижнем или верхнем регистрах.
        Последующие символы могут являться символами-разделителями
        '.' или '_', а так же символами нижнего или верхнего регистров.

        :param stamp: Уникальный алиас для группы
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/checkGroupStamp",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"stamp": stamp},
            },
        )

