    @api_version_check(min_version=47)
    @tracer.start_as_current_span("chats.rapi_blockChatMember")
    def rapi_blockChatMember(
        self,
        sn: str,
        members: List[dict[str, str]],
        deleteLastMessages: bool = True,
    ) -> dict:
        """
        Заблокирует участников members в чате sn.
        В зависимости от параметров блокировка будет
        с удалением последних сообщений пользователей.
        :param sn: Идентификатор группы
        :param members: Список идентификаторов группы
        :param deleteLastMessages: Флаг для удаления последних сообщений
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/blockChatMembers",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {
                    "members": [{"sn": member} for member in members],
                    "sn": sn,
                    "deleteLastMessages": deleteLastMessages,
                },
            },
        )

    @api_version_check(min_version=47)
    @tracer.start_as_current_span("chats.rapi_unblockChatMembers")
    def rapi_unblockChatMembers(self, sn: str, members: List[str]) -> dict:
        """
        Разблокирует участников members в чате sn.
        :param sn: Идентификатор группы
        :param members: Список идентификаторов группы
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/unblockChatMembers",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {
                    "members": [{"sn": member} for member in members],
                    "sn": sn,
                },
            },
        )

    @api_version_check(min_version=13)
    @tracer.start_as_current_span("chats.rapi_getChatHome")
    def rapi_getChatHome(self, geo_lat: float, geo_lon: float, country: str = "RU"):
        """
        Получить витрину чатов/ботов
        :param geo_lat: geo-location of user
        :param geo_lon: geo-location of user
        :param country: optional, overrides country which we get by your IP
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/getChatHome",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {
                    "geo": {"lat": geo_lat, "lon": geo_lon},
                    "country": country,
                },
            },
        )

