    @tracer.start_as_current_span("chats.rapi_borrowHistory")
    def rapi_borrowHistory(
        self,
        sender_sn: str,
        sn: str,
        time_range_from: datetime,
        time_range_to: datetime,
        only_del_msgs: bool = False,
    ):
        return self.post(
            "rapi/borrowHistory",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "authToken": self.org_struct_admin_token,
                "clientId": 1,
                "params": {
                    "senderSn": sender_sn,
                    "sn": sn,
                    "timeRange": {
                        "from": int(time_range_from.timestamp()),
                        "to": int(time_range_to.timestamp()),
                    },
                    "onlyDelMsgs": only_del_msgs,
                    "patchVersion": "none",
                },
            },
        )
